const val=n=>(n/100).toFixed(2),monthNow=()=>D.today().slice(0,7),sum=a=>a.reduce((x,y)=>x+y,0);
let state,view='home',month=monthNow(),search='',filter='all',limit=60,analyticsPeriod='month',analyticsSection='all',analyticsCategory='all',analyticsAccount='all',analyticsSearch='',locked=false,busy=false,toastTimer,lastActivity=Date.now(),pendingImport=null,importKind='',draft=null,splitDraft=[],pendingURL=location.hash.slice(1);
const bc='BroadcastChannel'in window?new BroadcastChannel('stack-state'):null;
bc?.addEventListener('message',()=>toast('Данные изменены в другой вкладке. Перезагрузите Stack.'));
