function toast(text,undo){clearTimeout(toastTimer);const t=$('#toast');t.innerHTML=`<span>${e(text)}</span>${undo?'<button id="undo">Отменить</button>':''}`;t.className='visible';if(undo)$('#undo').onclick=undo;toastTimer=setTimeout(()=>t.className='',undo?5500:4500);}
async function change(fn){if(busy)throw Error('Дождитесь сохранения');busy=true;try{const next=structuredClone(state);fn(next);D.validateBackup(next);await persist(next,state.revision);state=next;bc?.postMessage('changed');return true;}finally{busy=false;}}
function theme(){const t=state.settings.theme;const mode=t==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):t;document.documentElement.dataset.theme=mode;document.querySelector('meta[name=theme-color]')?.setAttribute('content',mode==='dark'?'#101114':'#f2f3f7');}
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>state&&theme());
function modal(title,body,submit){sheet.innerHTML=`<div class="sheet-head"><h2>${e(title)}</h2><button type="button" data-close aria-label="Закрыть">${icon('close')}</button></div>${submit?'<form id="form">':''}${body}${submit?'<p id="form-error" class="error" role="alert"></p></form>':''}`;if(!sheet.open)sheet.showModal();if(submit)$('#form').onsubmit=async event=>{event.preventDefault();const button=event.submitter;try{if(button)button.disabled=true;await submit(new FormData(event.target));}catch(err){const el=$('#form-error');if(el)el.textContent=err.message;else toast(err.message);}finally{if(button)button.disabled=false;}};}
function close(){try{currentRecognition?.abort();}catch{}currentRecognition=null;sheet.close();draft=null;}
const field=(label,name,value='',type='text',extra='')=>`<label for="f-${name}">${e(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}>`;
const options=(items,selected)=>items.map(([id,label])=>`<option value="${e(id)}" ${id===selected?'selected':''}>${e(label)}</option>`).join('');
const select=(label,name,items,selected)=>`<label for="f-${name}">${e(label)}</label><select name="${name}" id="f-${name}">${options(items,selected)}</select>`;
const aopts=(include)=>state.accounts.filter(a=>!a.archived||include?.includes(a.id)).map(a=>[a.id,`${a.name} · ${a.currency}${a.archived?' · архив':''}`]);
const copts=(include)=>state.categories.filter(c=>!c.hidden||c.id===include).map(c=>[c.id,c.name]);
const saveButton=(text='Сохранить')=>`<button class="primary" type="submit">${text}</button>`;
const empty=(title,text,action,label)=>`<div class="empty">${icon('stack')}<h3>${e(title)}</h3><p>${e(text)}</p>${action?`<button class="primary" data-action="${action}">${label}</button>`:''}</div>`;
function nav(){return `<nav aria-label="Основная навигация">${[['home','home','Главная'],['history','history','История'],['add','plus','Добавить'],['analytics','chart','Аналитика'],['more','dots','Ещё']].map(([id,i,label])=>`<button data-nav="${id}" class="${id==='add'?'add':view===id?'active':''}" aria-label="${label}" ${view===id?'aria-current="page"':''}>${icon(i)}${id==='add'?'':`<span>${label}</span>`}</button>`).join('')}</nav>`;}
function render(){theme();if(locked){renderLock();return;}if(!state.accounts.length){onboard();return;}app.innerHTML=`<main class="container"><header><div class="brand">${icon('stack')}<span class="stack2-brand">STACK<small>ЛИЧНЫЕ ФИНАНСЫ</small></span></div><button class="plain" data-action="settings" aria-label="Настройки">${icon('dots')}</button></header>${({home,history,analytics,more})[view]()}</main>${nav()}`;}
function monthPicker(){return `<div class="month"><input type="month" id="month" aria-label="Месяц отчёта" value="${month}" min="2000-01" max="2100-12"></div>`;}
function txList(items){return items.length?`<div class="list">${items.map(t=>{const c=cat(t.categoryId),transfer=t.type==='transfer',a=acc(t.splits[0].accountId);return `<button class="list-item" data-action="editTx" data-id="${e(t.id)}"><span class="badge">${icon(transfer?'arrow':c?.icon)}</span><span class="grow"><strong>${e(t.note|| (transfer?'Перевод':c?.name))}</strong><small>${e(t.date.split('-').reverse().join('.'))} · ${e(a.name)}${t.splits.length>1&&!transfer?' + сплит':''}</small></span><span class="money ${t.type==='income'?'positive':''}">${transfer?'↔ ':t.type==='expense'?'−':'+'}${money(D.amount(t),transfer?acc(t.splits[1].accountId).currency:a.currency)}</span></button>`;}).join('')}</div>`:empty('Пока ни одной операции','Добавьте первую трату — баланс и лимит пересчитаются.','addTx','Добавить операцию');}
function home(){
 const current=monthNow(),st=D.stats(state,current),total=D.total(state),free=D.free(state,current);
 const due=D.unpaid(state,current).filter(r=>{const d=D.dueDate(r,current);return (new Date(d+'T12:00:00')-new Date(D.today()+'T12:00:00'))/86400000<=r.before;});
 const expenses=state.transactions.filter(t=>!t.deleted&&t.type==='expense'&&t.date.startsWith(current));
 const daily=new Map();for(const t of expenses)daily.set(t.date,(daily.get(t.date)||0)+D.txRub(state,t));
 const last7=Array.from({length:7},(_,i)=>{const d=new Date(D.today()+'T12:00:00');d.setDate(d.getDate()-(6-i));const k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return daily.get(k)||0});
 const maxDay=Math.max(1,...last7);
 const recent=state.transactions.filter(t=>!t.deleted).sort((a,b)=>b.date.localeCompare(a.date)||(b.created||'').localeCompare(a.created||'')).slice(0,5);
 const budgets=state.budgets[current]||[0,0,0];
 return `<div class="stack2-home">
  <div class="stack2-heading"><div><p class="eyebrow">ВАШИ ФИНАНСЫ</p><h1>Главная</h1></div><span class="stack2-private">${icon('shield')} Локально</span></div>
  ${due.map(r=>`<div class="stack2-alert"><span><strong>${e(r.name)}</strong><small>К оплате ${e(D.dueDate(r,current))} · ${money(r.amount,acc(r.accountId).currency)}</small></span><button data-action="pay" data-id="${e(r.id)}">Оплатить</button></div>`).join('')}
  ${state.settings.backupReminderDays!==0&&(!state.settings.lastBackup||Date.now()-Date.parse(state.settings.lastBackup)>(state.settings.backupReminderDays||7)*864e5)?`<div class="stack2-alert"><span>Давно не делали резервную копию</span><button data-action="backup">Сохранить</button></div>`:''}
  <section class="stack2-balance" aria-label="Баланс и динамика расходов">
    <div class="stack2-kicker">ОБЩИЙ БАЛАНС</div><div class="stack2-total">${money(total)}</div>
    <div class="stack2-free">Свободно <b>${money(free)}</b></div>
    <div class="stack2-spark" role="img" aria-label="Расходы за последние семь дней">${last7.map((v,i)=>`<span style="height:${Math.max(6,Math.round(v/maxDay*100))}%" title="${money(v)}" class="${i===6?'today':''}"></span>`).join('')}</div>
    <div class="stack2-chartcaption">Расходы за последние 7 дней</div>
  </section>
  <div class="stack2-metrics"><button data-nav="analytics" class="stack2-metric"><span class="stack2-dot green"></span><small>Доходы · месяц</small><strong class="positive">${money(st.income)}</strong></button><button data-nav="analytics" class="stack2-metric"><span class="stack2-dot red"></span><small>Расходы · месяц</small><strong class="negative">${money(st.expense)}</strong></button></div>
  <section class="stack2-card"><div class="stack2-section-top"><h2>Бюджеты</h2><button data-action="budgets">Настроить ${icon('chevron')}</button></div>
  ${D.sections.map((title,i)=>{const cap=budgets[i]||0,spent=st.budget?.[0]?.[i]??null;const actual=state.transactions.filter(t=>!t.deleted&&t.type==='expense'&&t.date.startsWith(current)&&(cat(t.categoryId)?.section??1)===i).reduce((a,t)=>a+D.txRub(state,t),0);const pct=cap?Math.min(100,Math.round(actual/cap*100)):0;return `<div class="stack2-budget"><div class="stack2-between"><span>${e(title)}</span><b>${money(actual)} <i>/ ${cap?money(cap):'без лимита'}</i></b></div><div class="stack2-track"><span class="${cap&&actual>cap?'over':''}" style="width:${pct}%"></span></div></div>`}).join('')}</section>
  <div class="stack2-section-top"><h2>Мои счета</h2><button data-action="accounts">Все ${icon('chevron')}</button></div>
  <div class="stack2-accountscroll">${active().map(a=>`<button class="stack2-account" data-action="account" data-id="${e(a.id)}"><small>${e(a.name)}</small><strong>${money(D.balance(state,a.id),a.currency)}</strong><span>${e(a.currency)}</span></button>`).join('')}</div>
  <div class="stack2-section-top"><h2>Последние операции</h2><button data-nav="history">История ${icon('chevron')}</button></div>${txList(recent)}
  <p class="stack2-footnote">Баланс и график рассчитаны по сохранённым операциям. Для добавления нажмите + в нижнем меню.</p>
 </div>`;
}
function history(){const items=state.transactions.filter(t=>!t.deleted&&t.date.startsWith(month)&&(filter==='all'||t.splits.some(p=>p.accountId===filter))&&`${t.note} ${cat(t.categoryId)?.name}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.created.localeCompare(a.created));return `<div class="stack2-page-title"><div><p class="eyebrow">ВАШИ ОПЕРАЦИИ</p><h1>История</h1></div>${monthPicker()}</div><div class="toolbar"><input id="search" placeholder="Поиск по заметке и категории" aria-label="Поиск операций" value="${e(search)}"><select id="account-filter" aria-label="Фильтр по счету">${options([['all','Все счета'],...state.accounts.map(a=>[a.id,a.name])],filter)}</select></div>${txList(items.slice(0,limit))}${items.length>limit?'<button class="gap" data-action="moreHistory">Показать ещё</button>':''}<p class="help">${items.length} операций · нажмите на запись, чтобы изменить её.</p>`;}
function analyticsDates(){
 const today=D.today(),d=new Date(today+'T12:00:00'),to=today;
 if(analyticsPeriod==='month')return {from:month+'-01',to:month+'-'+String(new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate()).padStart(2,'0')};
 if(analyticsPeriod==='all')return {from:'2000-01-01',to:'2100-12-31'};
 const n=Number(analyticsPeriod),start=new Date(d);start.setDate(start.getDate()-n+1);
 return {from:D.todayFromDate?D.todayFromDate(start):`${start.getFullYear()}-${String(start.getMonth()+1).padStart(2,'0')}-${String(start.getDate()).padStart(2,'0')}`,to};
}
function categoryIssue(t){
 if(t.type==='transfer'||t.deleted)return '';
 const c=cat(t.categoryId), n=(c?.name||'').toLocaleLowerCase('ru'), note=(t.note||'').toLocaleLowerCase('ru');
 if(!c)return 'Категория удалена';
 if(t.type==='expense' && /^(зарплата|премия|возврат долга|доход)/i.test(n))return 'Доходная категория у расхода';
 if(t.type==='income' && /^(продукты|кафе|транспорт|покупки|спорт|поездки|жильё|аренда)/i.test(n))return 'Расходная категория у дохода';
 const guess=D.suggestCategory(note,t.type);
 if(guess && guess.name.toLocaleLowerCase('ru')!==n && !/^(прочее|без категории)$/i.test(guess.name) && guess.confidence==='high'){
  if(n==='прочее'||n==='покупки')return `Возможно: ${guess.name}`;
 }
 return '';
}
function categoryAudit(){
 const issues=state.transactions.filter(t=>!t.deleted).map(t=>({t,issue:categoryIssue(t)})).filter(x=>x.issue);
 modal('Проверка категорий',`<p class="muted">Проверка отмечает только вероятные ошибки. Данные автоматически не меняются. Проверено операций: ${state.transactions.filter(t=>!t.deleted).length}. Замечаний: ${issues.length}.</p>${issues.length?`<div class="list">${issues.slice(0,80).map(({t,issue})=>`<button class="list-item" data-action="editTx" data-id="${e(t.id)}"><span class="grow"><strong>${e(t.note||cat(t.categoryId)?.name||'Операция')}</strong><small>${e(issue)} · ${e(t.date)}</small></span>${money(D.amount(t))}</button>`).join('')}</div>`:'<p>Явных проблем в категориях не найдено.</p>'}<p class="help">Сводка не доказывает корректность всех записей: неизвестные магазины и неоднозначные описания требуют ручной проверки.</p>`);
}
function analytics(){
 const {from,to}=analyticsDates(),base=state.transactions.filter(t=>!t.deleted&&t.date>=from&&t.date<=to&&t.type!=='transfer');
 const categories=state.categories.filter(c=>!c.hidden||base.some(t=>t.categoryId===c.id));
 const sectionIndex=analyticsSection==='all'?null:Number(analyticsSection);
 const tx=base.filter(t=>(analyticsAccount==='all'||t.splits.some(p=>p.accountId===analyticsAccount))&&(sectionIndex===null||(cat(t.categoryId)?.section??1)===sectionIndex)&&(analyticsCategory==='all'||t.categoryId===analyticsCategory)&&`${t.note||''} ${cat(t.categoryId)?.name||''}`.toLocaleLowerCase('ru').includes(analyticsSearch.toLocaleLowerCase('ru')));
 const expenses=tx.filter(t=>t.type==='expense'),incomes=tx.filter(t=>t.type==='income');
 const analyticsValue=t=>analyticsAccount==='all'?D.txRub(state,t):D.txRubForAccount(state,t,analyticsAccount);
 const total=a=>a.reduce((n,t)=>n+analyticsValue(t),0),exTotal=total(expenses),inTotal=total(incomes);
 const sums=new Map(),sections=[0,0,0],days=new Map();
 for(const t of expenses){const amount=analyticsValue(t);sums.set(t.categoryId,(sums.get(t.categoryId)||0)+amount);const sec=cat(t.categoryId)?.section??1;sections[sec]+=amount;days.set(t.date,(days.get(t.date)||0)+amount);}
 const sorted=[...sums.entries()].sort((a,b)=>b[1]-a[1]);const biggest=Math.max(1,...sorted.map(x=>x[1]));
 const accountOpts=[['all','Все счета'],...state.accounts.map(a=>[a.id,a.name])],secOpts=[['all','Все разделы'],...D.sections.map((name,i)=>[String(i),name])];
 const catOpts=[['all','Все категории'],...categories.filter(c=>sectionIndex===null||c.section===sectionIndex).map(c=>[c.id,c.name])];
 const dayEntries=[...days.entries()].sort((a,b)=>a[0].localeCompare(b[0])),dayMax=Math.max(1,...dayEntries.map(x=>x[1]));
 return `<div class="row between space"><div><p class="eyebrow">Анализ финансов</p><h1 style="margin:0">Статистика</h1></div></div>
 <section class="card analytics-filters">
 <div class="analytics-period">${[['7','7 дней'],['30','30 дней'],['90','90 дней'],['365','Год'],['month','Месяц'],['all','Всё']].map(([id,label])=>`<button type="button" class="${analyticsPeriod===id?'selected':''}" data-action="analyticsPeriod" data-id="${id}">${label}</button>`).join('')}</div>
 ${analyticsPeriod==='month'?`<div class="gap"><label class="help" for="month">Месяц отчёта</label>${monthPicker()}</div>`:''}
 <p class="help">Период: ${e(from.split('-').reverse().join('.'))} — ${e(to.split('-').reverse().join('.'))}</p>
 <div class="analytics-selects"><label>Раздел<select id="analytics-section">${options(secOpts,analyticsSection)}</select></label><label>Категория<select id="analytics-category">${options(catOpts,analyticsCategory)}</select></label><label>Счёт<select id="analytics-account">${options(accountOpts,analyticsAccount)}</select></label></div>
 <label class="help" for="analytics-search">Поиск по операциям</label><input id="analytics-search" placeholder="Например, поездка или абонемент" value="${e(analyticsSearch)}"/>
 <button type="button" class="plain small" data-action="analyticsReset">Сбросить фильтры</button>
 </section>
 <div class="metric-grid gap"><div class="card"><span class="muted">Расходы</span><strong>${money(exTotal)}</strong></div><div class="card"><span class="muted">Доходы</span><strong class="positive">${money(inTotal)}</strong></div></div>
 <div class="card gap"><div class="row between"><h2>Движение денег</h2><span class="${inTotal-exTotal<0?'negative':'positive'}">${money(inTotal-exTotal)}</span></div><div class="chart" role="img" aria-label="Расходы по датам">${dayEntries.length?dayEntries.map(([day,n])=>`<div class="bar" style="height:${Math.max(2,n/dayMax*100)}%" title="${e(day)}: ${money(n)}"></div>`).join(''):'<p class="help">В выбранном периоде расходов нет</p>'}</div><p class="help">График показывает дни с расходами в выбранной выборке.</p></div>
 <div class="card gap"><div class="row between"><h2>Структура расходов</h2><button type="button" class="plain small" data-action="categoryAudit">Проверить категории</button></div>
 ${exTotal?`<div class="bank-donut" style="background:conic-gradient(${sorted.map(([id,n],i)=>{const prefix=sorted.slice(0,i).reduce((v,[,a])=>v+a,0)/exTotal*100;return `${['#438dff','#52c6ad','#ffb65b','#a38cf5','#f47789','#9db0c1'][i%6]} ${prefix}% ${prefix+n/exTotal*100}%`}).join(',')})"><div><small>Всего расходов</small><strong>${money(exTotal)}</strong></div></div>`:'<p class="muted">Расходов за выбранный период нет.</p>'}
 <p class="help">Суммы и проценты рассчитаны по расходным операциям, без переводов между собственными счетами. Возвраты отображаются в доходах, но не вычитаются автоматически из исходной категории расходов.</p></div>
 <div class="card gap"><h2>По разделам</h2>${D.sections.map((name,i)=>`<button class="analytics-category-row" data-action="analyticsSectionPick" data-id="${i}"><span>${e(name)}</span><strong>${money(sections[i])} · ${exTotal?Math.round(sections[i]/exTotal*100):0}%</strong></button>`).join('')}</div>
 <div class="card gap"><h2>По категориям</h2>${sorted.map(([id,n])=>`<button class="analytics-category-item" data-action="analyticsCategoryPick" data-id="${e(id)}"><span class="row between"><span>${e(cat(id)?.name||'Без категории')}</span><strong>${money(n)} · ${exTotal?(n/exTotal*100).toFixed(1):0}%</strong></span><span class="progress"><span style="width:${n/biggest*100}%"></span></span></button>`).join('')||'<p class="help">Расходов по выбранным фильтрам нет.</p>'}<p class="help">Нажмите на категорию, чтобы увидеть её операции.</p></div>
 <div class="section-head"><h2>Операции · ${tx.length}</h2><button class="plain small" data-action="categoryAudit">Аудит категорий</button></div>${txList([...tx].sort((a,b)=>b.date.localeCompare(a.date)||(b.created||'').localeCompare(a.created||'')).slice(0,100))}
 ${tx.length>100?'<p class="help">Показаны первые 100 операций. Уточните фильтры, чтобы увидеть нужные.</p>':''}
 <p class="help">Категории «Спорт», «Поездки» и другие можно добавить через Ещё → Категории. В статистике отображаются реально записанные категории. Переводы между своими счетами исключены; возвраты долгов входят в денежный поток согласно типу операции.</p>`;
}

function more(){return `<div class="stack2-page-title"><div><p class="eyebrow">НАСТРОЙКИ И СЕРВИСЫ</p><h1>Ещё</h1></div></div><div class="list">${[['recurring','calendar','Платежи','Регулярные расходы и календарь'],['goals','target','Цели','Откладывайте на важное'],['loans','wallet','Долги и общие чеки','Кто, кому и сколько'],['templates','plus','Шаблоны','Быстрая запись привычных расходов'],['categories','basket','Категории','Настройте учёт под себя'],['categoryAudit','chart','Проверить категории','Возможные ошибки в старых операциях'],['accounts','stack','Счета','Управление и архив'],['import','download','Импорт данных','Stack, Money Radar и CSV'],['shortcuts','arrow','Команды и умный ввод','Текст, SMS и QR чека'],['widgetSync','chart','Виджет Scriptable','Передать данные на главный экран'],['settings','dots','Настройки','Тема, курсы, PIN и резервные копии']].map(([action,i,title,sub])=>`<button class="list-item" data-action="${action}"><span class="badge">${icon(i)}</span><span class="grow"><strong>${title}</strong><small>${sub}</small></span>${icon('chevron')}</button>`).join('')}</div><p class="help gap">Stack 2.0 · без аккаунта и рекламы.<br>Данные этого устройства не синхронизируются с другими. Периодически сохраняйте JSON-копию.</p>`;}
function onboard(){app.innerHTML=`<main class="container"><section class="onboard"><div class="mark">${icon('stack')}</div><div class="eyebrow">Финансы в своём ритме</div><h1>Меньше шума.<br>Больше ясности.</h1><p class="muted">Счета, повседневные траты и планы — в одной аккуратной стопке.</p><div class="card gap"><div class="row">${icon('shield')}<strong>Только на вашем устройстве</strong></div><p class="help">Без регистрации и облака. Начните со счёта и текущего остатка. Затем задайте месячные бюджеты.</p></div><button class="primary" data-action="account">Создать первый счёт</button><button class="plain" data-action="import">У меня есть резервная копия</button></section></main>`;}
function accountForm(id){const old=state.accounts.find(a=>a.id===id),a=old||{name:'',type:'debit',currency:'RUB',initial:0};modal(old?'Настройки счёта':'Новый счёт',field('Название','name',a.name,'text','required maxlength="60" placeholder="Например, Основная карта"')+select('Тип','type',[['debit','Дебетовый'],['cash','Наличные'],['credit','Кредитный'],['savings','Накопительный']],a.type)+select('Валюта','currency',[['RUB','Рубли · ₽'],['USD','Доллары · $'],['EUR','Евро · €']],a.currency)+field('Начальный остаток (может быть отрицательным)','initial',val(a.initial),'text','inputmode="decimal" required')+'<p class="help">Это остаток до первой записанной операции. Изменение пересчитает весь баланс. Валюту счёта с историей менять нельзя.</p>'+saveButton()+(old?`<button class="plain danger gap" type="button" data-action="archive" data-id="${e(id)}">${a.archived?'Вернуть из архива':'Архивировать счёт'}</button>`:''),async f=>{const currency=f.get('currency');if(old&&currency!==old.currency&&state.transactions.some(t=>t.splits.some(p=>p.accountId===id)))throw Error('Сначала создайте отдельный счёт в нужной валюте');const initial=D.cents(f.get('initial')),name=f.get('name').trim();if(!name)throw Error('Введите название');const first=!state.accounts.length;await change(s=>{const item={...a,id:id||D.uid(),name,type:f.get('type'),currency,initial,archived:a.archived||false};if(old)s.accounts[s.accounts.findIndex(x=>x.id===id)]=item;else s.accounts.push(item);});close();render();if(first)budgetForm();});}
function budgetForm(){const m=view==='home'?monthNow():month,b=state.budgets[m]||[0,0,0];modal('Бюджет на месяц',field('Месяц','month',m,'month','required min="2000-01" max="2100-12"')+D.sections.map((n,i)=>field(n+' · ₽','b'+i,val(b[i]),'text','inputmode="decimal" required')).join('')+'<p class="help">Дневной лимит использует только «Повседневные». Каждый месяц имеет отдельный бюджет. Будущие доходы в лимит не включаются.</p>'+saveButton(),async f=>{const b=[0,1,2].map(i=>D.cents(f.get('b'+i)));if(b.some(n=>n<0))throw Error('Бюджеты не могут быть отрицательными');await change(s=>s.budgets[f.get('month')]=b);close();render();});}
function txForm(id,seed={}){if(!active().length&&!id){accountForm();return;}const old=state.transactions.find(t=>t.id===id);draft=old?structuredClone(old):{id:D.uid(),type:seed.type||'expense',date:seed.date||D.today(),categoryId:seed.categoryId||state.categories.find(c=>!c.hidden&&c.name===(seed.type==='income'?'Зарплата':'Продукты'))?.id||state.categories.find(c=>!c.hidden)?.id,note:seed.note||'',created:new Date().toISOString(),...seed};splitDraft=old?old.splits.map(p=>({accountId:p.accountId,value:val(Math.abs(p.amount))})):[{accountId:seed.accountId||active()[0].id,value:seed.amount?val(seed.amount):''}];const t=draft;modal(old?'Изменить операцию':t.type==='transfer'?'Перевод':'Новая операция',`${t.type!=='transfer'?select('Тип','type',[['expense','Расход'],['income','Доход']],t.type):''}${field('Сумма'+(t.type==='transfer'?' списания':''),'amount',old?val(t.type==='transfer'?Math.abs(t.splits[0].amount):D.amount(t)):seed.amount?val(seed.amount):'','text','inputmode="decimal" required placeholder="0,00"')}${t.type==='transfer'?select('Откуда','from',aopts(old?.splits.map(p=>p.accountId)),old?.splits[0].accountId||active()[0]?.id)+select('Куда','to',aopts(old?.splits.map(p=>p.accountId)),old?.splits[1].accountId||active()[1]?.id)+field('Зачислить (только для разных валют)','received',old?val(t.splits[1].amount):'','text','inputmode="decimal" placeholder="Для одной валюты заполнится автоматически"'):`${select('Категория','categoryId',copts(t.categoryId),t.categoryId)}<label>Оплата со счетов</label><div id="splits"></div><div class="row between"><button type="button" class="plain small" data-action="addSplit">+ Ещё счёт</button><button type="button" class="plain small" data-action="equalSplit">Поровну</button></div><p id="split-diff" class="help"></p>`}${field('Дата','date',t.date,'date','required')}${field('Заметка / магазин','note',t.note,'text','maxlength="500"')}${t.type==='expense'&&!old?'<details class="gap"><summary>Общий чек: мне должны часть суммы</summary>'+field('Имя должника','debtor','','text','maxlength="80"')+field('Его доля, ₽','debtAmount','','text','inputmode="decimal"')+'<p class="help">Для рублёвого чека. Расход сохраняется целиком; доля друга создаёт запись «мне должны».</p></details>':''}${saveButton(old?'Сохранить изменения':'Добавить операцию')}${old?`<button type="button" class="plain danger gap" data-action="deleteTx" data-id="${e(id)}">Удалить операцию</button>`:''}`,async f=>{const n=D.cents(f.get('amount'));if(n<=0)throw Error('Сумма должна быть больше нуля');let splits;if(t.type==='transfer'){const from=f.get('from'),to=f.get('to');if(from===to)throw Error('Выберите разные счета');const other=acc(from).currency!==acc(to).currency,received=other?D.cents(f.get('received')):n;if(received<=0)throw Error('Укажите сумму зачисления');splits=[{accountId:from,amount:-n},{accountId:to,amount:received}];}else{captureSplits();splits=splitDraft.map(p=>({accountId:p.accountId,amount:(f.get('type')==='expense'?-1:1)*(splitDraft.length===1?n:D.cents(p.value))}));if(sum(splits.map(p=>Math.abs(p.amount)))!==n)throw Error('Сумма сплитов не совпадает с общей суммой');}
 const tx={...t,type:t.type==='transfer'?'transfer':f.get('type'),splits,date:f.get('date'),note:f.get('note').trim(),categoryId:t.type==='transfer'?undefined:f.get('categoryId'),updated:new Date().toISOString()};D.validateTx(state,tx);
 const debtor=f.get('debtor')?.trim(),debtValue=f.get('debtAmount')?.trim();let debt=0;if(debtor||debtValue){if(tx.type!=='expense'||splits.some(p=>acc(p.accountId).currency!=='RUB'))throw Error('Общий чек доступен для расходов в рублях');debt=D.cents(debtValue);if(!debtor||debt<=0||debt>n)throw Error('Укажите имя и долю не больше чека');}
 await change(s=>{if(old)s.transactions[s.transactions.findIndex(x=>x.id===id)]=tx;else{s.transactions.push(tx);if(debt)s.loans.push({id:D.uid(),name:debtor,remaining:debt,original:debt,direction:'owed',transactionId:tx.id,date:tx.date});}});close();render();toast('Операция сохранена');});if(t.type!=='transfer')renderSplits();}
function captureSplits(){if(!$('#splits'))return;splitDraft=[...sheet.querySelectorAll('.split-row')].map(r=>({accountId:r.querySelector('select').value,value:r.querySelector('input').value}));}
function renderSplits(){const total=$('#f-amount').value;$('#splits').innerHTML=splitDraft.map((p,i)=>`<div class="split-row"><select aria-label="Счёт ${i+1}">${options(aopts([p.accountId]),p.accountId)}</select><input aria-label="Сумма со счёта ${i+1}" inputmode="decimal" value="${e(splitDraft.length===1?total:p.value)}" ${splitDraft.length===1?'disabled':''}><button type="button" data-remove-split="${i}" aria-label="Убрать счёт" ${splitDraft.length===1?'disabled':''}>×</button></div>`).join('');splitDiff();}
function splitDiff(){try{const n=D.cents($('#f-amount').value||'0');if(splitDraft.length===1){$('#splits input').value=$('#f-amount').value;$('#split-diff').textContent='Вся сумма с одного счёта';}else{$('#split-diff').textContent='Разница: '+money(n-sum([...sheet.querySelectorAll('.split-row input')].map(el=>D.cents(el.value||'0'))));}}catch{$('#split-diff').textContent='Проверьте суммы';}}
function recurringForm(id){if(!active().length)return accountForm();const r=state.recurring.find(x=>x.id===id)||{name:'',amount:0,day:1,accountId:active()[0].id,categoryId:state.categories[0].id,before:1};modal(id?'Изменить платёж':'Регулярный платёж',field('Название','name',r.name,'text','required maxlength="80"')+field('Сумма в валюте счёта','amount',r.amount?val(r.amount):'','text','inputmode="decimal" required')+field('День месяца','day',r.day,'number','min="1" max="31" required')+select('Счёт','accountId',aopts([r.accountId]),r.accountId)+select('Категория','categoryId',copts(r.categoryId),r.categoryId)+select('Напоминать за','before',[[0,'В день платежа'],[1,'1 день'],[3,'3 дня'],[7,'7 дней']].map(([n,t])=>[String(n),t]),String(r.before))+'<p class="help">Показываем баннер при открытии. В коротком месяце — последний день. Платёж не списывается автоматически.</p>'+saveButton()+(id?`<button type="button" class="plain danger gap" data-action="deleteRecurring" data-id="${e(id)}">Удалить расписание</button>`:''),async f=>{const amount=D.cents(f.get('amount'));if(amount<=0)throw Error('Сумма должна быть больше нуля');await change(s=>{const item={id:id||D.uid(),name:f.get('name').trim(),amount,day:Number(f.get('day')),accountId:f.get('accountId'),categoryId:f.get('categoryId'),before:Number(f.get('before'))};if(id)s.recurring[s.recurring.findIndex(x=>x.id===id)]=item;else s.recurring.push(item);});close();render();});}
function recurringList(){modal('План платежей',`<div class="row"><button class="primary" data-action="recurringForm">+ Платёж</button><button data-action="ics">В календарь</button></div><p class="help">Оплата отмечается за выбранный месяц. Повторное списание исключено.</p>${monthPicker()}${state.recurring.map(r=>{const paid=!D.unpaid(state,month).some(x=>x.id===r.id);return `<div class="card gap"><div class="row between"><div><strong>${e(r.name)}</strong><div class="help">${D.dueDate(r,month)} · ${money(r.amount,acc(r.accountId).currency)}</div></div><button class="plain small" data-action="recurringForm" data-id="${e(r.id)}">Изменить</button></div><button class="small gap" data-action="pay" data-month="${month}" data-id="${e(r.id)}" ${paid?'disabled':''}>${paid?'Оплачено':'Отметить оплату'}</button></div>`;}).join('')||'<p class="muted gap">Добавьте ипотеку, связь или подписку.</p>'}`);}
function goalsList(){modal('Мои цели',`<button class="primary" data-action="goal">+ Новая цель</button><p class="help">Сумма цели — резерв в рублях. Пополнение не списывает деньги со счетов. Не учитывайте эти же деньги второй раз как отдельный расход.</p>${state.goals.map(g=>`<div class="card gap"><div class="row between"><strong>${e(g.name)}</strong><button class="plain small" data-action="goal" data-id="${e(g.id)}">Изменить</button></div><div class="big gap">${money(g.saved)}</div><div class="progress"><span style="width:${Math.min(100,g.saved/g.target*100)}%"></span></div><p class="help">из ${money(g.target)}</p><button data-action="goalAdd" data-id="${e(g.id)}">Пополнить / снять</button></div>`).join('')}`);}
function goalForm(id){const g=state.goals.find(x=>x.id===id)||{name:'',target:0,saved:0};modal(id?'Изменить цель':'Новая цель',field('Название','name',g.name,'text','required maxlength="80"')+field('Нужно накопить, ₽','target',g.target?val(g.target):'','text','inputmode="decimal" required')+field('Уже отложено, ₽','saved',val(g.saved),'text','inputmode="decimal" required')+saveButton()+(id?`<button class="plain danger gap" type="button" data-action="deleteGoal" data-id="${e(id)}">Удалить цель</button>`:''),async f=>{const target=D.cents(f.get('target')),saved=D.cents(f.get('saved'));if(target<=0||saved<0)throw Error('Проверьте суммы');await change(s=>{const item={id:id||D.uid(),name:f.get('name').trim(),target,saved};if(id)s.goals[s.goals.findIndex(x=>x.id===id)]=item;else s.goals.push(item);});close();render();goalsList();});}
function loanForm(){modal('Добавить долг',field('Имя / название','name','','text','required maxlength="80"')+select('Кто должен','direction',[['owed','Мне должны'],['owe','Я должен']],'owed')+field('Остаток долга, ₽','amount','','text','inputmode="decimal" required')+'<p class="help">Это учёт уже существующего долга, без изменения счетов. Если деньги передали сейчас, отдельно внесите расход или доход.</p>'+saveButton(),async f=>{const amount=D.cents(f.get('amount'));if(amount<=0)throw Error('Сумма должна быть больше нуля');await change(s=>s.loans.push({id:D.uid(),name:f.get('name').trim(),direction:f.get('direction'),remaining:amount,original:amount,date:D.today()}));close();render();loansList();});}
function loansList(){modal('Долги',`<button class="primary" data-action="loan">+ Добавить долг</button><p class="help">Для возврата долга нажмите «Возврат» напротив должника — деньги будут зачислены на выбранный счёт. Рублёвые долги. Общий чек можно разделить при добавлении расхода.</p>${state.loans.map(l=>`<div class="card gap"><div class="row between"><strong>${e(l.name)}</strong><span class="pill">${l.direction==='owed'?'Мне должны':'Я должен'}</span></div><div class="big gap">${money(l.remaining)}</div><div class="row gap">${l.remaining?`<button data-action="repay" data-id="${e(l.id)}">Возврат</button>`:'<span class="positive">Погашен</span>'}<button class="plain danger" data-action="deleteLoan" data-id="${e(l.id)}">Удалить</button></div></div>`).join('')}`);}
function repayForm(id){const l=state.loans.find(x=>x.id===id),accounts=active().filter(a=>a.currency==='RUB');if(!accounts.length){toast('Создайте рублёвый счёт для возврата');return;}modal('Возврат: '+l.name,field('Сумма, ₽','amount',val(l.remaining),'text','inputmode="decimal" required')+select(l.direction==='owed'?'Зачислить на счёт':'Списать со счёта','accountId',accounts.map(a=>[a.id,a.name]),accounts[0].id)+field('Дата','date',D.today(),'date','required')+saveButton('Подтвердить возврат'),async f=>{const n=D.cents(f.get('amount'));if(n<=0||n>l.remaining)throw Error('Сумма больше остатка долга или равна нулю');await change(s=>{s.loans.find(x=>x.id===id).remaining-=n;s.transactions.push({id:D.uid(),type:l.direction==='owed'?'income':'expense',date:f.get('date'),categoryId:s.categories.find(c=>c.name==='Прочее')?.id||s.categories[0].id,note:'Возврат долга: '+l.name,splits:[{accountId:f.get('accountId'),amount:l.direction==='owed'?n:-n}],loanId:id,created:new Date().toISOString()});});close();render();loansList();});}
function templateForm(id){if(!active().length)return accountForm();const t=state.templates.find(x=>x.id===id)||{name:'',amount:0,accountId:active()[0].id,categoryId:state.categories[0].id};modal(id?'Изменить шаблон':'Быстрая трата',field('Название','name',t.name,'text','required maxlength="80"')+field('Сумма','amount',t.amount?val(t.amount):'','text','inputmode="decimal" required')+select('Счёт','accountId',aopts([t.accountId]),t.accountId)+select('Категория','categoryId',copts(t.categoryId),t.categoryId)+saveButton()+(id?`<button type="button" class="plain danger gap" data-action="deleteTemplate" data-id="${e(id)}">Удалить шаблон</button>`:''),async f=>{const amount=D.cents(f.get('amount'));if(amount<=0)throw Error('Сумма должна быть больше нуля');await change(s=>{const item={id:id||D.uid(),name:f.get('name').trim(),amount,accountId:f.get('accountId'),categoryId:f.get('categoryId')};if(id)s.templates[s.templates.findIndex(x=>x.id===id)]=item;else s.templates.push(item);});close();render();});}
function categoriesList(){modal('Категории',`<button class="primary" data-action="category">+ Категория</button>${D.sections.map((name,i)=>`<h3 class="gap">${name}</h3><div class="list gap">${state.categories.filter(c=>c.section===i).map(c=>`<button class="list-item" data-action="category" data-id="${e(c.id)}"><span class="grow">${e(c.name)}${c.hidden?' · скрыта':''}</span>${icon('chevron')}</button>`).join('')}</div>`).join('')}`);}
function categoryForm(id){const c=cat(id)||{name:'',section:1,hidden:false};modal(id?'Изменить категорию':'Новая категория',field('Название','name',c.name,'text','required maxlength="60"')+select('Раздел бюджета','section',D.sections.map((n,i)=>[String(i),n]),String(c.section))+`<label><input name="hidden" type="checkbox" ${c.hidden?'checked':''}> Скрыть из новых операций</label><p class="help">Изменение названия и раздела применяется и к истории.</p>`+saveButton(),async f=>{await change(s=>{const item={...c,id:id||D.uid(),name:f.get('name').trim(),section:Number(f.get('section')),hidden:f.has('hidden'),icon:c.icon||'dots'};if(id)s.categories[s.categories.findIndex(x=>x.id===id)]=item;else s.categories.push(item);});close();render();categoriesList();});}
function settings(){const s=state.settings;modal('Настройки',`<form id="settings-form"><h3>Оформление</h3><div class="theme-toggle-row"><span class="theme-toggle-title">Тёмная тема<small>Выключено — светлая, включено — тёмная</small></span><label class="ios-switch"><input id="theme-switch" type="checkbox" role="switch" aria-label="Тёмная тема" ${s.theme==='dark'||(s.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches)?'checked':''}><span class="ios-switch-track"></span></label></div><p class="help">Оформление применяется сразу и сохраняется после закрытия приложения.</p><h3 class="gap">Курсы валют → рубли</h3><p class="help">Курсы пересчитывают сводный баланс, но не изменяют исходные операции. Онлайн-источник — публичное зеркало данных ЦБ РФ.</p><div class="form-row">${field('1 USD = ₽','USD',s.rates.USD,'number','step="0.0001" min="0.0001" max="1000000" required')}${field('1 EUR = ₽','EUR',s.rates.EUR,'number','step="0.0001" min="0.0001" max="1000000" required')}</div><p class="help" id="rate-info">${s.rateSource?e(s.rateSource)+' · ': 'Ручные курсы · '}${e(s.rateOfficialDate||s.ratesDate||'Дата не установлена')}${s.rateFetchedAt?' · загружено '+e(new Date(s.rateFetchedAt).toLocaleString('ru-RU')):''}</p><button class="secondary-action" type="button" id="update-rates">↻ Получить курсы из интернета</button><button class="primary gap" type="submit">Сохранить настройки</button></form><div class="section-head"><h3>Защита и данные</h3></div><label for="reminder-select">Напоминание о резервной копии</label><select id="reminder-select"><option value="7" ${(s.backupReminderDays??7)===7?'selected':''}>Раз в неделю</option><option value="30" ${s.backupReminderDays===30?'selected':''}>Раз в месяц</option><option value="0" ${s.backupReminderDays===0?'selected':''}>Отключено</option></select><div class="list gap">${[['pin',s.pin?'Изменить / убрать PIN':'Установить PIN'],['backup','Сохранить JSON-копию'],['secureBackup','Зашифрованная резервная копия'],['checkBackup','Проверить резервную копию'],['exportCSV','Экспорт операций CSV'],['import','Импорт / восстановление'],['shortcuts','Как установить и настроить Команды']].map(([act,title])=>`<button class="list-item" data-action="${act}"><span class="grow">${title}</span>${icon('chevron')}</button>`).join('')}${s.pin?'<button class="list-item" data-action="lock">Заблокировать сейчас</button>':''}</div><p class="help">PIN ограничивает доступ к экрану, но не шифрует IndexedDB. Зашифрованная резервная копия защищается отдельным паролем. На iOS сохранение файла необходимо завершить вручную.</p>`);
 $('#theme-switch').onchange=async ev=>{const chosen=ev.target.checked?'dark':'light';document.documentElement.dataset.theme=chosen;try{await change(s=>s.settings.theme=chosen);theme();toast(chosen==='dark'?'Тёмная тема включена':'Светлая тема включена');}catch(err){toast(err.message);}};

 $('#reminder-select').onchange=async ev=>{try{await change(s=>s.settings.backupReminderDays=Number(ev.target.value));toast('Напоминание обновлено');}catch(err){toast(err.message);}};
 $('#update-rates').onclick=async()=>{const button=$('#update-rates');button.disabled=true;button.textContent='Загружаем…';try{const data=await fetchCBR(AbortSignal.timeout(12000));await change(s=>{s.settings.rates=data.rates;s.settings.ratesDate=D.today();s.settings.rateOfficialDate=data.rateDate;s.settings.rateFetchedAt=data.fetchedAt;s.settings.rateSource=data.source;});$('#settings-form [name=USD]').value=data.rates.USD;$('#settings-form [name=EUR]').value=data.rates.EUR;$('#rate-info').textContent=data.source+' · курс от '+data.rateDate+' · загружено '+new Date(data.fetchedAt).toLocaleString('ru-RU');render();toast('Курсы обновлены');}catch(err){toast('Курсы не обновлены: '+err.message+'. Доступен ручной ввод.');}finally{button.disabled=false;button.textContent='↻ Получить курсы из интернета';}};
 $('#settings-form').onsubmit=async ev=>{ev.preventDefault();try{const f=new FormData(ev.target);await change(s=>{const usd=Number(f.get('USD')),eur=Number(f.get('EUR'));if(!Number.isFinite(usd)||!Number.isFinite(eur)||usd<=0||eur<=0||usd>1e6||eur>1e6)throw Error('Проверьте курсы');const changed=usd!==s.settings.rates.USD||eur!==s.settings.rates.EUR;s.settings.rates={RUB:1,USD:usd,EUR:eur};if(changed){s.settings.ratesDate=D.today();s.settings.rateSource='Ручной ввод';s.settings.rateOfficialDate=null;s.settings.rateFetchedAt=null;}});close();render();toast('Настройки сохранены');}catch(err){toast(err.message);}};}
async function hashPin(pin,salt){if(!crypto.subtle)throw Error('Для PIN откройте приложение по HTTPS (GitHub Pages)');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bits)).map(n=>n.toString(16).padStart(2,'0')).join('');}
function pinForm(){modal('PIN-код',`${state.settings.pin?field('Текущий PIN','current','','password','inputmode="numeric" pattern="[0-9]{4,6}" required autocomplete="off"'):''}${field('Новый PIN: 4–6 цифр','pin','','password','inputmode="numeric" pattern="[0-9]{4,6}" autocomplete="off"')}${field('Повторите новый PIN','repeat','','password','inputmode="numeric" pattern="[0-9]{4,6}" autocomplete="off"')}<p class="help">${state.settings.pin?'Оставьте новый PIN пустым, чтобы отключить блокировку.':'Запомните PIN. Для восстановления доступа понадобится сохранённая копия.'}</p>${saveButton()}`,async f=>{if(state.settings.pin&&await hashPin(f.get('current'),state.settings.pin.salt)!==state.settings.pin.hash)throw Error('Текущий PIN неверный');const pin=f.get('pin');if(pin!==f.get('repeat'))throw Error('Коды не совпадают');if(pin&&!/^\d{4,6}$/.test(pin))throw Error('Нужно 4–6 цифр');const salt=D.uid(),value=pin?{salt,hash:await hashPin(pin,salt)}:null;await change(s=>s.settings.pin=value);close();render();toast(value?'PIN установлен':'PIN отключён');});}
let failures=0,waitUntil=0;
function renderLock(){app.innerHTML=`<main class="container"><form id="unlock" class="lock"><div style="margin:auto">${icon('shield')}</div><h1 class="gap">Stack закрыт</h1><p class="muted">Введите PIN-код</p><input name="pin" aria-label="PIN" type="password" inputmode="numeric" pattern="[0-9]{4,6}" maxlength="6" autocomplete="off" required><button class="primary">Открыть</button><p id="lock-error" class="error" role="alert"></p><p class="help">Код защищает экран этого приложения.</p></form></main>`;$('#unlock').onsubmit=async ev=>{ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;try{if(Date.now()<waitUntil)throw Error('Подождите 30 секунд перед следующей попыткой');if(await hashPin(new FormData(ev.target).get('pin'),state.settings.pin.salt)!==state.settings.pin.hash){failures++;if(failures>=5){waitUntil=Date.now()+30000;failures=0;}throw Error('Неверный PIN');}failures=0;locked=false;lastActivity=Date.now();render();consumeURL();}catch(err){$('#lock-error').textContent=err.message;}finally{b.disabled=false;}};}
function lock(){if(!state.settings.pin)return;close();locked=true;render();}
async function download(content,name,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function backup(){const out=backupSnapshot(state);const date=new Date().toISOString();out.settings.lastBackup=date;backupSummary(out);await download(JSON.stringify(out,null,2),`Stack-backup-${D.today()}.json`);if(confirm('Файл действительно сохранён в приложении «Файлы» или на диске? Нажмите ОК только после проверки.')){await change(s=>s.settings.lastBackup=date);render();toast('Резервная копия отмечена как сохранённая');}else toast('Файл подготовлен; сохранение не подтверждено.');}
async function secureBackup(){modal('Зашифрованная копия',`<p class="muted">Шифрование AES-256-GCM. Запомните пароль: восстановить его будет невозможно.</p>${field('Пароль (минимум 10 символов)','password','','password','required minlength="10" autocomplete="new-password"')}${field('Повторить пароль','repeat','','password','required minlength="10" autocomplete="new-password"')}${saveButton('Подготовить защищённый файл')}`,async f=>{if(f.get('password')!==f.get('repeat'))throw Error('Пароли не совпадают');const out=backupSnapshot(state),encrypted=await encryptBackup(out,f.get('password'));await download(JSON.stringify(encrypted),`Stack-secure-${D.today()}.stack.json`);const saved=confirm('Проверьте, что зашифрованный файл сохранён в «Файлы» или на диске. Подтвердить сохранение?');if(saved)await change(s=>s.settings.lastBackup=new Date().toISOString());close();render();toast(saved?'Сохранение копии подтверждено':'Файл подготовлен, сохранение не подтверждено');});}
function checkBackup(){modal('Проверка копии',`<p class="muted">Можно проверить JSON или зашифрованную копию без изменения текущих данных.</p><input id="verify-file" type="file" accept=".json,.stack,application/json"><div id="verify-result" class="help" role="status"></div>`);$('#verify-file').onchange=async ev=>{const target=$('#verify-result');try{const file=ev.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Файл слишком большой');let data=JSON.parse(await file.text());if(data.format==='stack-encrypted'){const password=prompt('Введите пароль копии');if(password===null)return;data=await decryptBackup(data,password);}const info=backupSummary(data);target.textContent=`✓ Копия корректна: ${info.accounts} счетов, ${info.transactions} операций, ${info.categories} категорий. Текущие данные не изменены.`;}catch(err){target.textContent='Ошибка проверки: '+err.message;}};}
function exportCSV(){const q=x=>'"'+String(x??'').replaceAll('"','""')+'"';const rows=[['date','type','amount','currency','account','category','note','transaction_id']];for(const t of state.transactions.filter(t=>!t.deleted))for(const p of t.splits)rows.push([t.date,t.type,val(p.amount),acc(p.accountId).currency,acc(p.accountId).name,cat(t.categoryId)?.name||'',t.note,t.id]);download('\uFEFF'+rows.map(r=>r.map(q).join(';')).join('\r\n'),'Stack-operations.csv','text/csv;charset=utf-8');toast('Для полного восстановления используйте JSON, а не CSV.');}
function importDialog(){modal('Импорт данных',`<p class="muted">JSON-копия Stack восстанавливает всю базу. Полный экспорт Money Radar переносит операции, долги, цели, платежи, шаблоны и бюджеты. Старый JSON и CSV добавляют только операции.</p><label for="import-file">Выберите JSON или CSV</label><input type="file" id="import-file" accept=".json,.stack,.csv,text/csv,application/json"><p id="import-error" class="error" role="alert"></p><p class="help">Поддерживается CSV с колонками date (или Дата), amount (или Сумма), type, note. Без type: минус — расход, плюс — доход. Банковские форматы отличаются: пример есть в архиве. Перед восстановлением сохраните текущую JSON-копию.</p>`);$('#import-file').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Максимальный размер — 20 МБ');const text=await file.text();if(file.name.toLowerCase().endsWith('.json')){const parsed=JSON.parse(text);if(parsed.format==='stack-encrypted'){const password=prompt('Введите пароль защищённой копии');if(password===null)return;pendingImport=await decryptBackup(parsed,password);importKind='stack';restorePreview();return;}if(parsed.format==='stack'){D.validateBackup(parsed);pendingImport=parsed;importKind='stack';restorePreview();return;}if(parsed.format==='money-radar-stack-full'||parsed.moneyRadarOriginal){pendingImport=parsed;importKind='money-full';fullMoneyPreview();return;}pendingImport=D.legacyCandidates(parsed);importKind='money';}else{pendingImport=D.csvCandidates(text);importKind='csv';}if(!active().length)throw Error('Сначала создайте счёт для импорта операций');importPreview();}catch(err){if($('#import-error'))$('#import-error').textContent=err.message;else toast(err.message);}};}
function restorePreview(){modal('Восстановление Stack',`<div class="card"><strong>${pendingImport.accounts.length} счетов · ${pendingImport.transactions.filter(t=>!t.deleted).length} операций</strong><p class="help">Текущая база будет заменена целиком. PIN из файла не переносится. Текущий PIN этого устройства сохраняется.</p></div><button type="button" class="gap" data-action="backup">Сначала сохранить текущую копию</button><label><input type="checkbox" name="confirm" required> Заменить текущие данные этой копией</label>${saveButton('Восстановить')}`,async()=>{const next=structuredClone(pendingImport),pin=state.settings.pin;await change(s=>{const revision=s.revision;Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,next,{revision});s.settings.pin=pin;s.transactions.forEach(t=>{t.created=t.created||new Date().toISOString();});});pendingImport=null;close();render();toast('Резервная копия восстановлена');});}
function fullMoneyPreview(){
 const info=inspectMoneyRadar(pendingImport),n=info.counts;
 if(!active().some(a=>a.currency==='RUB'))throw Error('Сначала создайте рублёвый счёт');
 const m=monthNow();
 modal('Полный перенос Money Radar',`<p><strong>Найдено:</strong> ${n.transactions} операций, ${n.loans} долгов, ${n.goals} целей, ${n.recurring} регулярных платежей, ${n.templates} шаблонов.</p><p class="help">Импорт объединяет данные с текущим Stack и пропускает совпадения. Старые данные не удаляются. Дополнительные поля Money Radar остаются в исходном JSON-файле.</p>${select('Рублёвый счёт для операций','accountId',active().filter(a=>a.currency==='RUB').map(a=>[a.id,a.name]),active().find(a=>a.currency==='RUB').id)}<label><input type="checkbox" name="budget"> Перенести бюджеты на ${m} (заменит бюджет этого месяца)</label><label><input type="checkbox" name="initial"> Добавить начальный баланс Money Radar к выбранному счёту (может изменить общий баланс)</label><p class="help">Начальный баланс по умолчанию НЕ переносится, поскольку расходы уже импортированы. Остатки и связь долгов с исходными чеками проверьте после переноса. Не загружайте один и тот же начальный баланс дважды.</p>${saveButton('Объединить данные')}`,async f=>{
 const opts={accountId:f.get('accountId'),budgetMonth:f.has('budget')?m:null,importInitial:f.has('initial')};
 const {state:next,report}=mergeMoneyRadar(state,pendingImport,opts);
 D.validateBackup(next);
 const message=`Операций: +${report.transactions} (совпадений ${report.duplicates}); долгов: +${report.loans}; целей: +${report.goals}; регулярных: +${report.recurring}; шаблонов: +${report.templates}; категорий: +${report.categories}; пропущено: ${report.skipped.length}.`;
 if(report.skipped.length)throw Error('Обнаружены некорректные записи. Импорт отменён: '+report.skipped.slice(0,5).join('; '));
 if(!confirm(message+'\n\nПодтвердить перенос?'))return;
 await change(s=>{const revision=s.revision;Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,next,{revision});});pendingImport=null;close();render();toast('Money Radar: перенос выполнен');
 });
}
function importPreview(){const items=pendingImport;modal('Проверка импорта',`<p><strong>${items.length} операций</strong> · ${importKind==='money'?'Money Radar':'CSV'}</p>${select('На счёт (суммы в его валюте)','accountId',aopts(),active()[0]?.id)}${select('Категория по умолчанию','categoryId',copts(),state.categories.find(c=>c.name==='Прочее')?.id)}<p class="help">Будут пропущены совпадения по дате, типу, сумме, счёту и заметке. Старые категории Money Radar сопоставляются по имени.</p><div class="list gap">${items.slice(0,8).map(t=>`<div class="list-item"><span class="grow"><strong>${e(t.note||t.categoryName||t.type)}</strong><small>${t.date}</small></span><strong>${t.type==='expense'?'−':'+'}${(t.amount/100).toLocaleString('ru-RU')}</strong></div>`).join('')}</div>${items.length>8?'<p class="help">Показаны первые 8 записей.</p>':''}${saveButton('Добавить операции')}`,async f=>{const accountId=f.get('accountId');let added=0,skipped=0;await change(s=>{for(const item of items){const p={accountId,amount:item.type==='expense'?-item.amount:item.amount};if(s.transactions.some(t=>!t.deleted&&t.date===item.date&&t.type===item.type&&(t.note||'')===(item.note||'')&&t.splits.length===1&&t.splits[0].accountId===accountId&&t.splits[0].amount===p.amount)){skipped++;continue;}s.transactions.push({id:D.uid(),date:item.date,type:item.type,note:item.note||'',categoryId:s.categories.find(c=>c.name.toLowerCase()===item.categoryName?.toLowerCase())?.id||f.get('categoryId'),splits:[p],created:new Date().toISOString()});added++;}});pendingImport=null;close();render();toast(`Добавлено: ${added}, совпадений пропущено: ${skipped}`);});}
let currentRecognition=null;
function voiceForm(){modal('Голосовая операция',`<p class="muted">Произнесите операцию и проверьте сумму перед сохранением. Распознавание в некоторых браузерах использует сторонние сервисы.</p><button type="button" id="voice-start" class="primary">🎙 Начать запись</button><button type="button" id="voice-stop" class="secondary-action" disabled>Остановить</button><p id="voice-status" class="help" role="status">${recognitionAvailable()?'Нажмите «Начать запись»':'Распознавание недоступно. Нажмите поле ниже и используйте микрофон клавиатуры iPhone.'}</p><label for="voice-text">Распознанный текст (можно редактировать)</label><textarea id="voice-text" autofocus placeholder="Например: потратил 750 рублей на продукты"></textarea><button type="button" id="voice-parse" class="primary gap">Проверить операцию</button>`);
 const status=$('#voice-status'),start=$('#voice-start'),stop=$('#voice-stop');if(!recognitionAvailable()){start.hidden=true;setTimeout(()=>$('#voice-text')?.focus(),50);}
 function stopVoice(){try{currentRecognition?.stop();}catch{}currentRecognition=null;stop.disabled=true;start.disabled=!recognitionAvailable();}
 start.onclick=()=>{try{status.textContent='Слушаю…';start.disabled=true;stop.disabled=false;currentRecognition=startRecognition({onResult:text=>{$('#voice-text').value=text;status.textContent='Распознано. Открываю операцию для проверки…';setTimeout(()=>{if($('#voice-text')){stopVoice();openParsedText(text);}},250);},onError:err=>{status.textContent=err;},onEnd:()=>{stopVoice();}});}catch(err){stopVoice();status.textContent=err.message;}};
 stop.onclick=stopVoice;$('#voice-parse').onclick=()=>{const text=$('#voice-text').value.trim();if(!text){status.textContent='Введите или произнесите текст операции';return;}stopVoice();openParsedText(text);};
}
function openParsedText(text){try{const parsed=D.parseText(text),keywords=[[/кафе|coffee|кофе|ресторан/i,'Кафе'],[/пятероч|пятёроч|магнит|продукт|супермаркет|магазин/i,'Продукты'],[/такси|taxi|транспорт|бензин/i,'Транспорт'],[/зарплат/i,'Зарплата'],[/преми/i,'Премия']];const guess=keywords.find(([re])=>re.test(parsed.note||text));parsed.categoryId=state.categories.find(c=>c.name===guess?.[1])?.id||state.categories.find(c=>c.name==='Прочее')?.id;txForm(undefined,parsed);}catch(err){toast('Не удалось разобрать: '+err.message);}}
// STACK 2.2: единая точка ввода. Распознанные значения всегда открываются в форме проверки.
function intakeHub(){
 modal('Добавить операцию',`<div class="stack-intake-grid">
 <button type="button" data-action="expenseQuick">✏️<strong>Быстрый расход</strong><small>Сумма и категория</small></button>
 <button type="button" data-action="voice">🎙<strong>Голос</strong><small>Диктовка и проверка</small></button>
 <button type="button" data-action="receiptCapture">📷<strong>Фото чека</strong><small>Камера или галерея</small></button>
 <button type="button" data-action="notificationPaste">📋<strong>Банк / SMS</strong><small>Вставить уведомление</small></button>
 <button type="button" data-action="receiptQR">▦<strong>QR чека</strong><small>Сканирование QR</small></button>
 <button type="button" data-action="templates">☆<strong>Шаблоны</strong><small>Привычные траты</small></button>
 <button type="button" data-action="recurring">↻<strong>Платежи</strong><small>Регулярные расходы</small></button>
 <button type="button" data-action="import">⇩<strong>Выписка</strong><small>Импорт CSV</small></button>
 </div><p class="help gap">Распознанные суммы всегда проверяются перед сохранением. Нет доступа к SMS и уведомлениям без вашего участия.</p>`)
}
function notificationPaste(){
 modal('Текст банковской операции',`<p class="help">Скопируйте текст уведомления и вставьте его сюда. Остаток на счёте не принимается за сумму покупки.</p>
 <label for="bank-text">Текст уведомления</label><textarea id="bank-text" placeholder="Покупка 1 250 ₽. Магазин. Остаток 9 000 ₽"></textarea>
 <button type="button" id="bank-review" class="primary gap">Проверить расход</button><p class="help" id="bank-status" role="status"></p>`)
 $('#bank-review').onclick=()=>{const value=$('#bank-text').value.trim();if(!value){$('#bank-status').textContent='Вставьте текст уведомления';return;}try{openParsedText(value);}catch(err){const el=$('#bank-status');if(el)el.textContent=err.message;else toast(err.message);}}
}
function receiptCapture(mode='text'){
 modal(mode==='qr'?'QR-код чека':'Фото чека',`<p class="help">${mode==='qr'?'Выберите фото с QR-кодом или используйте камеру.':'Выберите фотографию чека или сделайте снимок.'} Распознавание зависит от возможностей браузера; если оно недоступно, введите итог вручную.</p>
 <label for="receipt-file">Изображение чека</label><input id="receipt-file" type="file" accept="image/*" capture="environment">
 <p id="receipt-status" class="help" role="status"></p>
 <label for="receipt-raw">${mode==='qr'?'Строка QR (можно вставить вручную)':'Распознанный текст (можно исправить)'}</label>
 <textarea id="receipt-raw" placeholder="${mode==='qr'?'t=20261101T1010&s=1250.00&fn=...':'ИТОГО 1 250,00 ₽'}"></textarea>
 <button type="button" class="primary gap" id="receipt-review">Проверить операцию</button>`)
 const status=$('#receipt-status'),raw=$('#receipt-raw');
 $('#receipt-file').onchange=async event=>{
  const file=event.target.files?.[0];if(!file)return;
  if(file.size>15*1024*1024){status.textContent='Максимальный размер изображения — 15 МБ';return;}
  status.textContent='Обрабатываем изображение…';
  try{
   const bitmap=await createImageBitmap(file);
   if(mode==='qr'&&'BarcodeDetector' in window){
    const detector=new window.BarcodeDetector({formats:['qr_code']});const codes=await detector.detect(bitmap);
    if(codes.length){raw.value=codes[0].rawValue;status.textContent='QR прочитан. Проверьте сумму перед сохранением.';}else status.textContent='QR не найден. Вставьте его содержимое вручную.';
   }else if(mode!=='qr'&&'TextDetector' in window){
    const detector=new window.TextDetector();const lines=await detector.detect(bitmap);
    raw.value=lines.map(line=>line.rawValue).join('\n');status.textContent=lines.length?'Текст распознан. Проверьте итоговую сумму.':'Текст не найден. Введите сумму вручную.';
   }else status.textContent='В этом браузере распознавание изображения недоступно. Используйте текст с чека или введите сумму вручную.';
   bitmap.close?.();
  }catch(err){status.textContent='Не удалось обработать изображение: '+err.message;}
 };
 $('#receipt-review').onclick=()=>{
  try{const text=raw.value.trim();if(!text)throw Error('Введите текст или реквизиты чека');
   // Фискальный QR имеет ключ s. Преобразование без внешних запросов.
   if(mode==='qr'&&!/(?:^|[?&])s=/.test(text))throw Error('Не найдена сумма s= в фискальном QR');
   openParsedText(text);
  }catch(err){const el=$('#receipt-status');if(el)el.textContent=err.message;else toast(err.message);}
 }
}
function smartForm(text=''){modal('Из текста или QR чека',`<label for="smart-text">SMS, текст траты или содержимое QR</label><textarea id="smart-text" name="text" required placeholder="Покупка 450,50 RUB. Кафе. Остаток 12 000 RUB">${e(text)}</textarea><p class="help">Вставьте текст SMS вручную. Для QR используйте системный сканер / Команды и вставьте строку вида t=20261030T1444&s=450.50&fn=… Сумма и дата откроются для проверки.</p>${saveButton('Разобрать текст')}`,f=>{const parsed=D.parseText(f.get('text'));const guess=D.suggestCategory(parsed.note,parsed.type);parsed.categoryId=state.categories.find(c=>c.name.toLowerCase()===guess?.name.toLowerCase())?.id||state.categories.find(c=>c.name==='Прочее')?.id;txForm(undefined,parsed);});}
function shortcuts(){const base=location.href.split('#')[0].split('?')[0];modal('Установка и Команды',`<h3>На iPhone</h3><p class="muted">Откройте страницу в Safari → «Поделиться» → «На экран Домой». Запустите с иконки и один раз дождитесь сообщения «Готово к работе офлайн».</p><h3>На Android</h3><p class="muted">В меню Chrome выберите «Установить приложение» или «Добавить на главный экран».</p><h3>Быстрый ввод из Команд</h3><p class="muted">В приложении «Команды»: «Запросить ввод» (текст) → «Кодировать URL» → «Текст» (ссылка ниже + закодированный ввод) → «Открыть URL».</p><div class="code">${e(base)}#text=ЗАКОДИРОВАННЫЙ_ТЕКСТ</div><p class="help">Текст после # не передаётся серверу GitHub. После разбора ссылка очищается. Операция всегда требует подтверждения. Для отдельной суммы: #add=1&amount=450.50&type=expense&note=Кофе</p><p class="help">Команды могут открывать Safari отдельно от установленного PWA. Проверьте, что видите свои счета перед сохранением. Если хранилища различаются, вставляйте текст внутри Stack.</p><h3>Голос и чеки</h3><p class="muted">При желании замените запрос текста действием «Диктовать текст» или сканированием QR в Командах. Обработка голоса зависит от настроек iOS и может использовать сеть. Сам Stack не записывает звук и не отправляет текст на распознавание.</p><button class="primary" data-action="smart">Открыть умный ввод</button>`);}
function consumeURL(){if(locked||!state.accounts.length||!pendingURL)return;const input=pendingURL;pendingURL='';window.history.replaceState(null,'',location.pathname+location.search);const q=new URLSearchParams(input);try{if(q.has('text'))smartForm(q.get('text').slice(0,5000));else if(q.has('add')){const n=D.cents(q.get('amount')||'0');if(n<=0)throw Error('В ссылке отсутствует сумма');txForm(undefined,{amount:n,type:q.get('type')==='income'?'income':'expense',note:(q.get('note')||'').slice(0,500)});}}catch(err){toast(err.message);}}
window.addEventListener('hashchange',()=>{pendingURL=location.hash.slice(1);consumeURL();});
function confirmAction(title,text,fn){modal(title,`<p class="muted">${e(text)}</p><button type="submit" class="primary">Подтвердить</button>`,async()=>{await fn();close();render();});}
async function deleteTx(id){const t=state.transactions.find(t=>t.id===id);if(t.loanId){toast('Возврат долга нельзя редактировать. Удаление восстановит остаток долга.');}const linked=state.loans.find(l=>l.transactionId===id);if(linked){toast('Сначала удалите связанную запись долга в разделе «Долги».');return;}await change(s=>{s.transactions.find(t=>t.id===id).deleted=true;if(t.loanId){const l=s.loans.find(l=>l.id===t.loanId);if(l)l.remaining+=D.amount(t);}});close();render();toast('Операция удалена',async()=>{try{await change(s=>{s.transactions.find(t=>t.id===id).deleted=false;if(t.loanId){const l=s.loans.find(l=>l.id===t.loanId);if(l){if(l.remaining<D.amount(t))throw Error('Долг уже изменён');l.remaining-=D.amount(t);}}});render();toast('Удаление отменено');}catch(err){toast(err.message);}});}

function stackWidgetSync(){
 const m=D.today().slice(0,7),st=D.stats(state,m);
 const expenses=state.transactions.filter(t=>!t.deleted&&t.type==='expense'&&t.date.startsWith(m));
 const buckets=new Map();
 for(const t of expenses){const label=cat(t.categoryId)?.name||'Без категории';buckets.set(label,(buckets.get(label)||0)+D.txRub(state,t));}
 const categories=[...buckets.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5).map(([name,amount])=>({name:name.slice(0,28),amount:Math.round(amount)/100}));
 const recent=state.transactions.filter(t=>!t.deleted&&t.type!=='transfer').sort((a,b)=>b.date.localeCompare(a.date)||(b.created||'').localeCompare(a.created||'')).slice(0,3).map(t=>({title:String(t.note||cat(t.categoryId)?.name||'Операция').slice(0,32),amount:Math.round(D.txRub(state,t))/100,type:t.type,date:t.date}));
 const payload={format:'stack-widget-v1',date:new Date().toISOString(),period:m,balance:Math.round(D.total(state))/100,free:Math.round(D.free(state,m))/100,todayLimit:Math.round(Math.max(0,st.leftToday))/100,income:Math.round(st.income)/100,expense:Math.round(st.expense)/100,categories,recent,url:location.href.split('#')[0].split('?')[0]};
 const link='scriptable:///run?scriptName=Stack%20Widget&parameter='+encodeURIComponent(JSON.stringify(payload));
 modal('Обновление виджета Stack',`<p class="muted">Передать в Scriptable сводку, пять категорий расходов и последние операции за текущий месяц.</p><button class="primary" id="send-stack-widget">Передать данные</button><p class="help">Обновление по нажатию. Scriptable не может автоматически читать локальную базу Stack. Не публикуйте ссылку с финансовыми данными.</p>`);
 $('#send-stack-widget').onclick=()=>{location.href=link;};
}

const actions={
 categoryAudit,analyticsPeriod:id=>{analyticsPeriod=id;render();},analyticsSectionPick:id=>{analyticsSection=id;analyticsCategory="all";render();},analyticsCategoryPick:id=>{analyticsCategory=id;render();},analyticsReset:()=>{analyticsPeriod="month";analyticsSection="all";analyticsCategory="all";analyticsAccount="all";analyticsSearch="";render();},
 widgetSync:stackWidgetSync,
 settings,account:accountForm,budgets:budgetForm,intake:intakeHub,notificationPaste,receiptCapture:()=>receiptCapture('text'),receiptQR:()=>receiptCapture('qr'),addTx:()=>txForm(),incomeQuick:()=>txForm(undefined,{type:'income',categoryId:state.categories.find(c=>c.name==='Зарплата')?.id}),expenseQuick:()=>txForm(undefined,{type:'expense'}),transfer:()=>{if(active().length<2){toast('Создайте второй счёт для перевода');return;}txForm(undefined,{type:'transfer'});},editTx:id=>{const t=state.transactions.find(t=>t.id===id);if(state.loans.some(l=>l.transactionId===id)){modal('Общий чек',`<p>${e(t.note||cat(t.categoryId)?.name)}</p><p class="big">${money(D.amount(t))}</p><p class="help">К этому чеку привязан долг. Чтобы изменить или удалить чек, сначала удалите связанную запись долга и при необходимости создайте её заново с правильным остатком. Денежные операции возврата сохранятся.</p><button data-action="loans">Открыть долги</button>`);return;}if(t.loanId){modal('Возврат долга',`<p>${e(t.note)}</p><p class="big">${money(D.amount(t))}</p><p class="help">Чтобы изменить возврат, удалите его и внесите заново. Остаток долга восстановится.</p><button class="danger" data-action="deleteTx" data-id="${e(id)}">Удалить возврат</button>`);return;}txForm(id);},deleteTx,
 archive:async id=>{const a=acc(id);if(!a.archived){if(active().length===1)throw Error('Нужен хотя бы один активный счёт');if(state.recurring.some(r=>r.accountId===id)||state.templates.some(t=>t.accountId===id))throw Error('Сначала перенесите шаблоны и платежи на другой счёт');}await change(s=>s.accounts.find(a=>a.id===id).archived=!a.archived);close();render();},
 accounts:()=>modal('Все счета',`<button class="primary" data-action="account">+ Новый счёт</button><div class="list gap">${state.accounts.map(a=>`<button class="list-item" data-action="account" data-id="${e(a.id)}"><span class="grow">${e(a.name)}${a.archived?' · архив':''}</span><strong>${money(D.balance(state,a.id),a.currency)}</strong></button>`).join('')}</div>`),
 addSplit:()=>{captureSplits();const a=active().find(a=>!splitDraft.some(p=>p.accountId===a.id)&&a.currency===acc(splitDraft[0].accountId).currency);if(!a)throw Error('Нужен ещё один счёт в той же валюте');splitDraft.push({accountId:a.id,value:''});renderSplits();},equalSplit:()=>{captureSplits();const n=D.cents($('#f-amount').value),v=Math.floor(n/splitDraft.length);splitDraft.forEach((p,i)=>p.value=val(v+(i===0?n-v*splitDraft.length:0)));renderSplits();},
 moreHistory:()=>{limit+=60;render();},recurring:recurringList,recurringForm,
 pay:(id,button)=>{const r=state.recurring.find(r=>r.id===id),m=button?.dataset.month||monthNow();if(!D.unpaid(state,m).some(r=>r.id===id))throw Error('Этот платёж уже оплачен');modal('Оплата: '+r.name,`<p class="big">${money(r.amount,acc(r.accountId).currency)}</p><p class="muted">Со счёта ${e(acc(r.accountId).name)} · за ${m}</p>${field('Фактическая дата оплаты','date',D.today(),'date','required')}${saveButton('Подтвердить оплату')}`,async f=>{await change(s=>{if(!D.unpaid(s,m).some(r=>r.id===id))throw Error('Уже оплачено');s.transactions.push({id:D.uid(),type:'expense',date:f.get('date'),categoryId:r.categoryId,note:r.name,splits:[{accountId:r.accountId,amount:-r.amount}],recurringId:r.id,recurringMonth:m,created:new Date().toISOString()});});close();render();toast('Платёж записан');});},
 ics:()=>{if(!state.recurring.length)throw Error('Сначала добавьте платёж');download(D.ics(state),'Stack-payments.ics','text/calendar;charset=utf-8');toast('Откройте файл в календаре и подтвердите импорт');},
 deleteRecurring:id=>confirmAction('Удалить расписание?','История оплаченных операций сохранится.',()=>change(s=>s.recurring=s.recurring.filter(r=>r.id!==id))),
 goals:goalsList,goal:goalForm,goalAdd:id=>{const g=state.goals.find(g=>g.id===id);modal('Резерв: '+g.name,field('Сумма, ₽ (минус — снять из резерва)','amount','','text','inputmode="decimal" required')+saveButton(),async f=>{const n=D.cents(f.get('amount'));if(g.saved+n<0)throw Error('В резерве недостаточно денег');await change(s=>s.goals.find(g=>g.id===id).saved+=n);close();render();goalsList();});},deleteGoal:id=>confirmAction('Удалить цель?','Резерв освободится. Балансы счетов не изменятся.',()=>change(s=>s.goals=s.goals.filter(g=>g.id!==id))),
 loans:loansList,loan:loanForm,repay:repayForm,deleteLoan:id=>confirmAction('Удалить запись долга?','История денежных операций сохранится; остаток долга больше не будет отслеживаться.',()=>change(s=>{s.loans=s.loans.filter(l=>l.id!==id);s.transactions.forEach(t=>{if(t.loanId===id)delete t.loanId;});})),
 template:templateForm,useTemplate:id=>{const t=state.templates.find(t=>t.id===id);txForm(undefined,{amount:t.amount,categoryId:t.categoryId,accountId:t.accountId,note:t.name});},templates:()=>modal('Шаблоны',`<button class="primary" data-action="template">+ Шаблон</button><div class="list gap">${state.templates.map(t=>`<button class="list-item" data-action="template" data-id="${e(t.id)}"><span class="grow">${e(t.name)}</span><strong>${money(t.amount,acc(t.accountId).currency)}</strong></button>`).join('')}</div>`),deleteTemplate:id=>confirmAction('Удалить шаблон?','Операции, созданные по шаблону, сохранятся.',()=>change(s=>s.templates=s.templates.filter(t=>t.id!==id))),
 categories:categoriesList,category:categoryForm,backup,secureBackup,checkBackup,exportCSV,import:importDialog,smart:()=>smartForm(),voice:voiceForm,shortcuts,pin:pinForm,lock
};
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-close')){close();return;}if(locked)return;if(b.dataset.nav){close();if(b.dataset.nav==='add')intakeHub();else{view=b.dataset.nav;limit=60;render();window.scrollTo({top:0,behavior:'instant'});}return;}if(b.dataset.removeSplit!==undefined){captureSplits();splitDraft.splice(Number(b.dataset.removeSplit),1);renderSplits();return;}const act=b.dataset.action;if(actions[act])await actions[act](b.dataset.id,b);}catch(err){toast(err.message);}});
document.addEventListener('input',ev=>{if(ev.target.id==='analytics-search'){const pos=ev.target.selectionStart;analyticsSearch=ev.target.value;render();const el=$('#analytics-search');if(el){el.focus();el.setSelectionRange(pos,pos);}}if(ev.target.id==='search'){const start=ev.target.selectionStart;search=ev.target.value;render();$('#search').focus();$('#search').setSelectionRange(start,start);}if(ev.target.id==='f-amount'&&$('#splits'))splitDiff();if(ev.target.closest('.split-row'))splitDiff();});
document.addEventListener('change',ev=>{if(ev.target.id==='month'){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(ev.target.value))return;month=ev.target.value;if(sheet.open)recurringList();else render();}if(ev.target.id==='account-filter'){filter=ev.target.value;render();}if(ev.target.id==='analytics-section'){analyticsSection=ev.target.value;analyticsCategory='all';render();}if(ev.target.id==='analytics-category'){analyticsCategory=ev.target.value;render();}if(ev.target.id==='analytics-account'){analyticsAccount=ev.target.value;render();}});
['pointerdown','keydown'].forEach(type=>document.addEventListener(type,()=>lastActivity=Date.now(),{passive:true}));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state?.settings.pin)lock();else if(!document.hidden&&state&&!locked)render();});
setInterval(()=>{if(state?.settings.pin&&!locked&&Date.now()-lastActivity>120000)lock();},15000);
try{state=await openDB();D.validateBackup(state);state.transactions.forEach(t=>t.created=t.created||'');locked=!!state.settings.pin;render();consumeURL();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js?v=2.2.0').then(reg=>{const announce=()=>toast('Доступно обновление. Закройте все окна Stack и откройте снова.');if(reg.waiting)announce();reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',()=>{if(reg.waiting&&navigator.serviceWorker.controller)announce();});});return navigator.serviceWorker.ready;}).then(()=>{if(!locked)toast('Готово к работе офлайн');}).catch(()=>toast('Офлайн-кэш не установлен. Проверьте HTTPS и файлы на GitHub.'));}if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});}catch(err){app.innerHTML=`<main class="container"><h1>Не удалось открыть Stack</h1><p>${e(err.message)}</p><p class="muted">Не очищайте данные браузера. Проверьте обычный режим Safari/Chrome, свободную память и HTTPS, затем перезагрузите страницу.</p></main>`;}
